import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.DBpCFmh2.js";const p=JSON.parse('{"title":"服务器架构","description":"本文面向本地代理服务 Agent（Node.js，包名 ai-helper-agent，版本 2.3.1）的服务器架构文档。","frontmatter":{"title":"服务器架构","description":"本文面向本地代理服务 Agent（Node.js，包名 ai-helper-agent，版本 2.3.1）的服务器架构文档。"},"headers":[],"relativePath":"本地代理服务/服务器架构/index.md","filePath":"本地代理服务/服务器架构/index.md","lastUpdated":null}'),i={name:"本地代理服务/服务器架构/index.md"};function l(n,e,s,g,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="服务器架构" tabindex="-1">服务器架构 <a class="header-anchor" href="#服务器架构" aria-label="Permalink to &quot;服务器架构&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js" target="_blank" rel="noreferrer">agent/src/config.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js" target="_blank" rel="noreferrer">agent/src/logger.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与容量特性">性能与容量特性</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#部署与运维">部署与运维</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文面向本地代理服务 Agent（Node.js，包名 ai-helper-agent，版本 2.3.1）的服务器架构文档。Agent 作为 Chrome 扩展的本地代理端，提供 HTTP API、WebSocket 实时通道、文件系统访问、命令执行、技能系统、MCP 工具注册与调用、长期记忆与 RAG 检索等能力。服务采用原生 Node.js <code>http</code> 模块与 <code>ws</code> 实现，不使用 Express；路由、中间件、认证、日志、配置、生命周期管理均集中在单入口文件中，并通过多个子模块解耦业务领域。</p><p>需要特别注意：Agent 是独立进程，源码或运行时配置修改后必须重启进程，新接口和配置才会生效。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>Agent 代码位于 <code>agent/</code> 目录，入口为 <code>src/server.js</code>，通过 <code>package.json</code> 暴露 CLI 命令 <code>ai-helper-agent</code> 与别名 <code>aha</code>。核心职责划分如下：</p><table tabindex="0"><thead><tr><th>层级</th><th>主要职责</th><th>关键文件</th></tr></thead><tbody><tr><td>服务入口</td><td>HTTP 请求处理、WebSocket 升级、生命周期、全局错误处理</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></td></tr><tr><td>配置中心</td><td>默认值、配置文件读写、内存缓存、写锁、配对信息</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js" target="_blank" rel="noreferrer">agent/src/config.js</a></td></tr><tr><td>审计日志</td><td>JSON Lines 日志、按日轮转、清理策略、查询接口</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js" target="_blank" rel="noreferrer">agent/src/logger.js</a></td></tr><tr><td>包元数据</td><td>版本号、入口、CLI、依赖、RAG 可选依赖</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></td></tr></tbody></table><pre class="mermaid">graph TB
Client[&quot;Chrome 扩展 / 本地客户端&quot;] --&gt; HTTP[&quot;HTTP 服务器&lt;br/&gt;原生 http 模块&quot;]
Client --&gt; WS[&quot;WebSocket 服务器&lt;br/&gt;ws 库&quot;]
HTTP --&gt; Router[&quot;统一请求处理器&lt;br/&gt;server.js&quot;]
Router --&gt; Config[&quot;配置模块&lt;br/&gt;config.js&quot;]
Router --&gt; Logger[&quot;审计日志模块&lt;br/&gt;logger.js&quot;]
Router --&gt; FS[&quot;文件系统操作&quot;]
Router --&gt; Exec[&quot;命令执行器&quot;]
Router --&gt; Memory[&quot;长期记忆路由&quot;]
Router --&gt; RAG[&quot;RAG 知识库路由&quot;]
Router --&gt; Skill[&quot;技能系统&quot;]
Router --&gt; MCP[&quot;MCP 工具注册与调用&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2086-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2086-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L163" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L163</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L65" target="_blank" rel="noreferrer">agent/src/server.js#L1-L65</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L10" target="_blank" rel="noreferrer">agent/package.json#L1-L10</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li><strong>HTTP 服务器</strong>：基于 Node.js <code>http.createServer</code>，所有路由在 <code>handleRequest</code> 中按路径分支处理，不依赖 Express。</li><li><strong>WebSocket 服务器</strong>：基于 <code>ws</code> 的 <code>WebSocketServer({ noServer: true })</code>，通过 <code>server.on(&#39;upgrade&#39;)</code> 接管 WebSocket 升级。</li><li><strong>配置系统</strong>：以 <code>~/.ai-helper-agent/config.json</code> 为持久化载体，带内存缓存、mtime 失效、写锁、字段校验、敏感字段加密落盘。</li><li><strong>日志系统</strong>：JSON Lines 格式，按天写入 <code>~/.ai-helper-agent/logs/agent-YYYY-MM-DD.log</code>，支持控制台输出、类别标签、自动清理、分页查询。</li><li><strong>安全与认证</strong>：Bearer Token 认证、CORS 仅放行 <code>chrome-extension://</code> 来源、路径白名单、命令分级检查、回收站机制。</li><li><strong>生命周期管理</strong>：启动时初始化搜索工具、RAG 探测、MCP/Skill 异步初始化；优雅关闭终止子进程、断开 WebSocket、关闭 HTTP/WebSocket 服务器、清理 PID 文件。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2086-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2086-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L41" target="_blank" rel="noreferrer">agent/src/config.js#L15-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L7-L11" target="_blank" rel="noreferrer">agent/src/logger.js#L7-L11</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>Agent 的服务架构可理解为“单进程多路由”模型：一个 HTTP 服务器承载 REST API，一个 WebSocket 服务器承载命令执行实时流；两者共享认证、配置、日志与安全策略。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;Chrome 扩展&quot;
participant HTTP as &quot;HTTP 服务器&quot;
participant Router as &quot;统一请求处理器&quot;
participant Auth as &quot;认证模块&quot;
participant FS as &quot;文件系统&quot;
participant Exec as &quot;命令执行器&quot;
participant WS as &quot;WebSocket 服务器&quot;
Ext-&gt;&gt;HTTP : POST /api/exec {command, cwd}
HTTP-&gt;&gt;Router : handleRequest(req,res)
Router-&gt;&gt;Auth : verifyToken(Bearer)
Auth--&gt;&gt;Router : extId
Router-&gt;&gt;FS : checkPath(cwd)
FS--&gt;&gt;Router : allowed
Router-&gt;&gt;Exec : executeCommand(command,cwd,callback)
Exec--&gt;&gt;Router : execId
Router--&gt;&gt;Ext : {execId, wsUrl}
Ext-&gt;&gt;WS : ws : //\${host} : \${port}/ws/exec/\${execId}?token=...
WS-&gt;&gt;Exec : addWsClient(execId,ws)
Exec--&gt;&gt;WS : 实时 stdout/stderr
WS--&gt;&gt;Ext : 事件流
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="http-服务器与路由机制" tabindex="-1">HTTP 服务器与路由机制 <a class="header-anchor" href="#http-服务器与路由机制" aria-label="Permalink to &quot;HTTP 服务器与路由机制&quot;">​</a></h3><p>HTTP 服务器由 <code>startServer</code> 创建，使用原生 <code>http.createServer</code>，所有请求进入 <code>handleRequest</code>。该函数承担以下职责：</p><ul><li>解析 URL、设置国际化语言上下文。</li><li>处理 CORS 预检与响应头。</li><li>区分无需认证接口与需认证接口。</li><li>按 pathname 分发到具体业务逻辑。</li><li>统一 JSON 响应封装。</li></ul><p>关键路由分组如下：</p><table tabindex="0"><thead><tr><th>分组</th><th>典型端点</th><th>行为</th></tr></thead><tbody><tr><td>无认证</td><td><code>/api/pair</code>、<code>/api/status</code></td><td>配对码生成、平台状态与健康检查</td></tr><tr><td>控制面</td><td><code>/api/shutdown</code>、<code>/api/agent/restart</code>、<code>/api/agent/update</code></td><td>本机免认证关闭、远程需认证；重启与更新带冷却与防重入</td></tr><tr><td>文件操作</td><td><code>/api/fs/read</code>、<code>/api/fs/write</code>、<code>/api/fs/list</code>、<code>/api/fs/download-stream</code></td><td>路径白名单校验、大小限制、脚本权限剥离、ZIP 打包、流式传输</td></tr><tr><td>命令执行</td><td><code>/api/exec</code>、<code>/api/exec/stop</code>、<code>/api/exec/detach</code></td><td>命令安全检查、同步/异步模式、返回 WebSocket 地址</td></tr><tr><td>技能系统</td><td><code>/api/skill/run</code>、<code>/api/skill/import</code>、<code>/api/skill/save-markdown</code></td><td>导入、启用、运行、Markdown 管理</td></tr><tr><td>MCP</td><td><code>/api/mcp/servers</code>、<code>/api/mcp/call</code></td><td>添加/删除/连接/断开/切换/调用</td></tr><tr><td>RAG</td><td><code>/api/rag/install</code>、<code>/api/rag/detect</code>、<code>/api/rag/*</code></td><td>可选依赖安装、检测、动态加载路由</td></tr><tr><td>长期记忆</td><td><code>/api/memory/*</code></td><td>静态加载 memory 路由</td></tr></tbody></table><pre class="mermaid">flowchart TD
Start([&quot;收到 HTTP 请求&quot;]) --&gt; ParseURL[&quot;解析 URL 与 pathname&quot;]
ParseURL --&gt; I18n[&quot;设置请求级 i18n 语言&quot;]
I18n --&gt; CORS{&quot;是否 OPTIONS 预检&quot;}
CORS --&gt; |是| Return204[&quot;返回 204 空响应&quot;]
CORS --&gt; |否| LoadConfig[&quot;每次请求重新加载配置&quot;]
LoadConfig --&gt; NoAuth{&quot;是否无需认证接口&quot;}
NoAuth --&gt; |是| HandleNoAuth[&quot;处理 pair/status/shutdown&quot;]
NoAuth --&gt; |否| CheckAuth[&quot;验证 Bearer Token&quot;]
CheckAuth --&gt; Valid{&quot;Token 有效？&quot;}
Valid --&gt; |否| Return401[&quot;返回 401/403&quot;]
Valid --&gt; |是| Route[&quot;按 pathname 分发到业务路由&quot;]
Route --&gt; FileOps[&quot;文件上传/读取/下载/搜索&quot;]
Route --&gt; ExecOps[&quot;命令执行&quot;]
Route --&gt; SkillOps[&quot;技能管理&quot;]
Route --&gt; McpOps[&quot;MCP 管理&quot;]
Route --&gt; RagOps[&quot;RAG 可选依赖与路由&quot;]
Route --&gt; MemoryOps[&quot;长期记忆路由&quot;]
FileOps --&gt; End([&quot;返回 JSON 或二进制流&quot;])
ExecOps --&gt; End
SkillOps --&gt; End
McpOps --&gt; End
RagOps --&gt; End
MemoryOps --&gt; End
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L553" target="_blank" rel="noreferrer">agent/src/server.js#L427-L553</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L862" target="_blank" rel="noreferrer">agent/src/server.js#L751-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1689" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1689</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1727-L1841" target="_blank" rel="noreferrer">agent/src/server.js#L1727-L1841</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2025-L2072" target="_blank" rel="noreferrer">agent/src/server.js#L2025-L2072</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L553" target="_blank" rel="noreferrer">agent/src/server.js#L427-L553</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L862" target="_blank" rel="noreferrer">agent/src/server.js#L751-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1689" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1689</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1727-L1841" target="_blank" rel="noreferrer">agent/src/server.js#L1727-L1841</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2025-L2072" target="_blank" rel="noreferrer">agent/src/server.js#L2025-L2072</a></li></ul><h3 id="中间件处理流程" tabindex="-1">中间件处理流程 <a class="header-anchor" href="#中间件处理流程" aria-label="Permalink to &quot;中间件处理流程&quot;">​</a></h3><p>Agent 没有传统意义上的 Express 中间件栈，而是通过 <code>handleRequest</code> 中的顺序判断模拟中间件效果：</p><ol><li><strong>国际化中间件</strong>：根据 <code>Accept-Language</code> 设置各子模块语言。</li><li><strong>CORS 中间件</strong>：仅放行 <code>chrome-extension://</code> 来源，OPTIONS 预检直接返回。</li><li><strong>配置刷新中间件</strong>：每次请求重新加载配置，避免 workdir 切换后快照过期。</li><li><strong>认证中间件</strong>：除少数无认证接口外，其余均需 Bearer Token。</li><li><strong>业务路由中间件</strong>：按路径分发给文件、命令、技能、MCP、RAG、记忆等模块。</li><li><strong>错误兜底中间件</strong>：顶层 try/catch 捕获未处理异常，返回 500。</li></ol><pre class="mermaid">flowchart TD
Req[&quot;请求进入&quot;] --&gt; Lang[&quot;设置 i18n 语言&quot;]
Lang --&gt; Options{&quot;OPTIONS?&quot;}
Options --&gt; |是| CorsPreflight[&quot;返回 CORS 预检&quot;]
Options --&gt; |否| ReloadCfg[&quot;重新加载配置&quot;]
ReloadCfg --&gt; AuthCheck{&quot;是否需要认证&quot;}
AuthCheck --&gt; |否| PublicRoute[&quot;处理公开接口&quot;]
AuthCheck --&gt; |是| VerifyToken[&quot;验证 Token&quot;]
VerifyToken --&gt; Valid{&quot;有效？&quot;}
Valid --&gt; |否| Reject[&quot;拒绝请求&quot;]
Valid --&gt; |是| Dispatch[&quot;分发到业务路由&quot;]
Dispatch --&gt; Resp[&quot;统一 JSON 响应&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L553" target="_blank" rel="noreferrer">agent/src/server.js#L427-L553</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L427-L553" target="_blank" rel="noreferrer">agent/src/server.js#L427-L553</a></li></ul><h3 id="错误处理策略" tabindex="-1">错误处理策略 <a class="header-anchor" href="#错误处理策略" aria-label="Permalink to &quot;错误处理策略&quot;">​</a></h3><p>错误处理分为三层：</p><table tabindex="0"><thead><tr><th>层级</th><th>处理方式</th></tr></thead><tbody><tr><td>请求级</td><td><code>parseBody</code>、<code>parseMultipartBody</code> 对超大 body、非法 JSON、非法 multipart 返回 400</td></tr><tr><td>路由级</td><td>每个业务分支 catch 异常并记录日志，返回结构化 <code>{success,error}</code></td></tr><tr><td>全局级</td><td><code>handleRequest</code> 外层 catch 返回 500；<code>uncaughtException</code>、<code>unhandledRejection</code> 监听记录但不退出进程</td></tr></tbody></table><p>此外，端口占用错误会直接退出进程，避免半开服务。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L271-L303" target="_blank" rel="noreferrer">agent/src/server.js#L271-L303</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L310-L383" target="_blank" rel="noreferrer">agent/src/server.js#L310-L383</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L425" target="_blank" rel="noreferrer">agent/src/server.js#L417-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2293-L2306" target="_blank" rel="noreferrer">agent/src/server.js#L2293-L2306</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2156-L2163" target="_blank" rel="noreferrer">agent/src/server.js#L2156-L2163</a></li></ul><h3 id="websocket-通信实现" tabindex="-1">WebSocket 通信实现 <a class="header-anchor" href="#websocket-通信实现" aria-label="Permalink to &quot;WebSocket 通信实现&quot;">​</a></h3><p>WebSocket 用于命令执行的实时数据推送。核心流程：</p><ol><li>HTTP 端点 <code>/api/exec</code> 返回 <code>wsUrl</code>。</li><li>客户端连接 <code>/ws/exec/{execId}</code>，优先使用 <code>Authorization: Bearer</code>，回退到 <code>?token=</code>。</li><li>服务端验证 token，失败直接 403。</li><li>将 WebSocket 加入执行器客户端列表。</li><li>心跳检测：每 30 秒 ping，未 pong 则 terminate。</li><li>客户端断开时移除连接，并按受管/旧语义处理超时。</li></ol><pre class="mermaid">sequenceDiagram
participant Client as &quot;客户端&quot;
participant HTTP as &quot;HTTP 服务器&quot;
participant WS as &quot;WebSocket 服务器&quot;
participant Exec as &quot;命令执行器&quot;
Client-&gt;&gt;HTTP : GET /api/exec
HTTP--&gt;&gt;Client : {execId, wsUrl}
Client-&gt;&gt;WS : 连接 ws : //\${host} : \${port}/ws/exec/\${execId}?token=...
WS-&gt;&gt;WS : 验证 Authorization 或 ?token
WS-&gt;&gt;Exec : addWsClient(execId, ws)
Exec--&gt;&gt;WS : 推送 stdout/stderr
WS--&gt;&gt;Client : 实时消息
Client-&gt;&gt;WS : 断开
WS-&gt;&gt;Exec : disconnectWsClient(execId, ws)
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1657-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1657-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1657-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1657-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li></ul><h3 id="服务生命周期管理" tabindex="-1">服务生命周期管理 <a class="header-anchor" href="#服务生命周期管理" aria-label="Permalink to &quot;服务生命周期管理&quot;">​</a></h3><p>生命周期包括启动、运行、关闭三个阶段：</p><ul><li><p><strong>启动阶段</strong>：</p><ul><li>加载配置，开启终端日志输出。</li><li>异步初始化搜索工具与 RAG 可用性检测。</li><li>创建 HTTP 服务器与 WebSocket 服务器。</li><li>启动配对码轮换、回收站定期清理。</li><li>异步初始化 MCP 与 Skill 注册表，并启动 Skill 目录监听。</li></ul></li><li><p><strong>运行阶段</strong>：</p><ul><li>处理 HTTP 请求与 WebSocket 升级。</li><li>维护活跃 socket 集合用于优雅关闭。</li><li>监控进程信号 SIGINT/SIGTERM。</li></ul></li><li><p><strong>关闭阶段</strong>：</p><ul><li>停止配对码轮换与周期任务。</li><li>中止 RAG 安装并回收 npm 进程树。</li><li>终止所有运行中的命令进程。</li><li>关闭 MCP 连接。</li><li>强制断开所有 WebSocket 客户端。</li><li>销毁活跃 HTTP socket，避免 <code>server.close()</code> 挂起。</li><li>等待 server 与 wss 关闭，清理 PID 文件，退出进程。</li><li>若 10 秒内未完成，强制退出防止卡死。</li></ul></li></ul><pre class="mermaid">stateDiagram-v2
[*] --&gt; 启动中
启动中 --&gt; 运行中 : &quot;HTTP 与 WebSocket 已监听&quot;
运行中 --&gt; 关闭中 : &quot;SIGINT/SIGTERM 或 /api/shutdown&quot;
关闭中 --&gt; 已关闭 : &quot;资源释放完成&quot;
关闭中 --&gt; 已关闭 : &quot;10 秒超时强制退出&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2165-L2205" target="_blank" rel="noreferrer">agent/src/server.js#L2165-L2205</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2288" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2288</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2290-L2291" target="_blank" rel="noreferrer">agent/src/server.js#L2290-L2291</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L425" target="_blank" rel="noreferrer">agent/src/server.js#L388-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2165-L2205" target="_blank" rel="noreferrer">agent/src/server.js#L2165-L2205</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2288" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2288</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2290-L2291" target="_blank" rel="noreferrer">agent/src/server.js#L2290-L2291</a></li></ul><h3 id="配置系统设计" tabindex="-1">配置系统设计 <a class="header-anchor" href="#配置系统设计" aria-label="Permalink to &quot;配置系统设计&quot;">​</a></h3><p>配置系统以 <code>~/.ai-helper-agent/config.json</code> 为核心，设计要点如下：</p><ul><li><strong>默认值合并</strong>：<code>DEFAULTS</code> 定义端口、主机、工作目录、允许路径、RAG 策略、记忆 embedding 等，用户配置覆盖默认值。</li><li><strong>内存缓存</strong>：<code>loadConfig</code> 使用 mtime 判断是否重新读取磁盘，减少 IO。</li><li><strong>写锁互斥</strong>：<code>withWriteLock</code> 保证并发写不会互相覆盖。</li><li><strong>敏感字段加密</strong>：<code>memoryEmbedding.apiKey</code> 与 pairing token 落盘前加密，内存中保持明文。</li><li><strong>自动白名单</strong>：skills 目录与工作目录自动加入 <code>allowedPaths</code>。</li><li><strong>字段校验</strong>：<code>updateConfigField</code> 仅允许合法 key，否则抛出国际化错误。</li></ul><p>环境变量方面，当前配置模块未直接读取环境变量；但日志模块支持 <code>AI_HELPER_LANG</code> 设置日志语言。Agent 启动参数与 CLI 行为由 <code>bin/agent.js</code> 与 <code>package.json</code> scripts 驱动。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L41" target="_blank" rel="noreferrer">agent/src/config.js#L15-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L107-L149" target="_blank" rel="noreferrer">agent/src/config.js#L107-L149</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L154-L188" target="_blank" rel="noreferrer">agent/src/config.js#L154-L188</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L193-L210" target="_blank" rel="noreferrer">agent/src/config.js#L193-L210</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L249-L269" target="_blank" rel="noreferrer">agent/src/config.js#L249-L269</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L32-L45" target="_blank" rel="noreferrer">agent/src/logger.js#L32-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L18-L25" target="_blank" rel="noreferrer">agent/package.json#L18-L25</a></li></ul><h3 id="性能监控、日志记录、健康检查与调试工具" tabindex="-1">性能监控、日志记录、健康检查与调试工具 <a class="header-anchor" href="#性能监控、日志记录、健康检查与调试工具" aria-label="Permalink to &quot;性能监控、日志记录、健康检查与调试工具&quot;">​</a></h3><ul><li><p><strong>健康检查</strong>：</p><ul><li><code>/api/status</code>：返回版本、平台、架构、Node 版本、搜索工具可用性与 RAG 可用性。</li><li><code>/api/status/detail</code>：需认证，返回内存使用、运行时长、CPU 时间、工作目录、允许路径、文件限制、运行进程等。</li><li><code>/api/heartbeat</code>：需认证，仅刷新在线状态。</li></ul></li><li><p><strong>性能监控</strong>：</p><ul><li>通过 <code>/api/status/detail</code> 获取 <code>memoryUsedMB</code>、<code>memoryTotalMB</code>、<code>memoryRssMB</code>、<code>uptimeSeconds</code>、<code>cpuUser</code>、<code>cpuSystem</code>。</li><li>文件下载支持流式传输，避免一次性读入内存导致 OOM。</li><li>ZIP 打包使用临时文件并在完成后删除。</li></ul></li><li><p><strong>日志记录</strong>：</p><ul><li>分类日志：auth、fs、exec、security、system。</li><li>控制台输出开关由 <code>setConsoleOutput(true)</code> 启用。</li><li>日志文件按日轮转，保留最多 30 个文件，单个文件超过 10MB 会被清理。</li><li>提供 <code>/api/logs/query</code> 查询最近 7 天日志，支持类别过滤与分页。</li></ul></li><li><p><strong>调试工具</strong>：</p><ul><li>审计日志查询接口便于前端展示。</li><li>平台信息与 RAG 探测结果可用于诊断环境差异。</li><li>Skill 目录监听自动重载，便于开发调试。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L725-L749" target="_blank" rel="noreferrer">agent/src/server.js#L725-L749</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1705-L1725" target="_blank" rel="noreferrer">agent/src/server.js#L1705-L1725</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1267-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1267-L1385</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L163" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L163</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L183-L228" target="_blank" rel="noreferrer">agent/src/logger.js#L183-L228</a></li></ul><h3 id="部署指南" tabindex="-1">部署指南 <a class="header-anchor" href="#部署指南" aria-label="Permalink to &quot;部署指南&quot;">​</a></h3><p>Agent 的官方安装渠道是 GitHub Releases 自动构建产物，不建议手动 clone 源码构建。部署时需关注以下方面：</p><ul><li><p><strong>Docker 容器化</strong>：</p><ul><li>基础镜像需满足 Node &gt;= 18。</li><li>暴露端口 <code>18910</code>（可通过配置修改）。</li><li>挂载 <code>~/.ai-helper-agent</code> 目录以持久化配置、workspace、memory、logs。</li><li>注意容器内用户权限与宿主目录映射。</li></ul></li><li><p><strong>环境变量设置</strong>：</p><ul><li><code>AI_HELPER_LANG</code>：设置日志语言（zh/en），默认检测系统语言。</li><li>其他运行时参数通过配置文件 <code>config.json</code> 设置，如 <code>port</code>、<code>host</code>、<code>workdir</code>、<code>allowedPaths</code>、<code>commandTimeout</code>、<code>fileMaxSize</code>。</li></ul></li><li><p><strong>端口配置</strong>：</p><ul><li>默认端口 <code>18910</code>，可在配置中修改。</li><li>端口占用时会退出进程，避免半开服务。</li></ul></li><li><p><strong>防火墙规则</strong>：</p><ul><li>建议仅开放 <code>127.0.0.1:18910</code>，避免暴露在公网。</li><li>若需远程访问，应通过反向代理或 SSH 隧道，并确保 Bearer Token 安全。</li></ul></li><li><p><strong>进程监控与自动重启</strong>：</p><ul><li>支持 <code>/api/agent/restart</code> 与 <code>/api/agent/update</code>，内部使用两阶段 spawn 重启包装器。</li><li>更新失败不重启，保持老进程运行并提示用户手动执行。</li><li>优雅关闭带 10 秒超时保护，防止进程卡死。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L10" target="_blank" rel="noreferrer">agent/package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L18-L25" target="_blank" rel="noreferrer">agent/package.json#L18-L25</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L44-L46" target="_blank" rel="noreferrer">agent/package.json#L44-L46</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/config.js#L15-L41" target="_blank" rel="noreferrer">agent/src/config.js#L15-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L32-L45" target="_blank" rel="noreferrer">agent/src/logger.js#L32-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L555-L603" target="_blank" rel="noreferrer">agent/src/server.js#L555-L603</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L605-L720" target="_blank" rel="noreferrer">agent/src/server.js#L605-L720</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2156-L2163" target="_blank" rel="noreferrer">agent/src/server.js#L2156-L2163</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2288" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2288</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>Agent 的核心依赖如下：</p><table tabindex="0"><thead><tr><th>依赖</th><th>用途</th></tr></thead><tbody><tr><td><code>ws</code></td><td>WebSocket 服务器</td></tr><tr><td><code>archiver</code></td><td>ZIP 打包</td></tr><tr><td><code>xlsx</code></td><td>Excel 预览解析</td></tr><tr><td><code>zod</code></td><td>数据校验（可能用于部分模块）</td></tr><tr><td><code>@modelcontextprotocol/sdk</code></td><td>MCP 协议支持</td></tr></tbody></table><p>RAG 相关依赖标记在 <code>ragDependencies</code> 中，按需安装，不影响主服务启动。</p><pre class="mermaid">graph TB
Server[&quot;server.js&quot;] --&gt; WS[&quot;ws&quot;]
Server --&gt; Archiver[&quot;archiver&quot;]
Server --&gt; XLSX[&quot;xlsx&quot;]
Server --&gt; Zod[&quot;zod&quot;]
Server --&gt; MCP[&quot;@modelcontextprotocol/sdk&quot;]
Server --&gt; Config[&quot;config.js&quot;]
Server --&gt; Logger[&quot;logger.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L26-L40" target="_blank" rel="noreferrer">agent/package.json#L26-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L56" target="_blank" rel="noreferrer">agent/src/server.js#L1-L56</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L26-L40" target="_blank" rel="noreferrer">agent/package.json#L26-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L56" target="_blank" rel="noreferrer">agent/src/server.js#L1-L56</a></li></ul><h2 id="性能与容量特性" tabindex="-1">性能与容量特性 <a class="header-anchor" href="#性能与容量特性" aria-label="Permalink to &quot;性能与容量特性&quot;">​</a></h2><ul><li><strong>请求体限制</strong>：JSON body 最大 200MB，multipart 上传同样限制。</li><li><strong>文件读取限制</strong>：默认 50MB，可通过 <code>fileMaxSize</code> 调整。</li><li><strong>流式上传</strong>：<code>/api/fs/upload-stream</code> 支持原始二进制流，避免 base64 膨胀。</li><li><strong>流式下载</strong>：<code>/api/fs/download-stream</code> 使用 <code>createReadStream</code> 或分块写入，避免内存峰值。</li><li><strong>ZIP 打包</strong>：临时文件写入 tmpdir，完成后删除，避免长期占用磁盘。</li><li><strong>日志清理</strong>：保留最近 30 个日志文件，单个文件超 10MB 清理，间隔 60 秒。</li><li><strong>WebSocket 心跳</strong>：30 秒 ping，检测半开连接，防止僵尸连接占用资源。</li></ul><p>[本节为通用性能讨论，不直接分析具体文件]</p><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><p>常见问题与定位方法：</p><table tabindex="0"><thead><tr><th>问题</th><th>排查步骤</th></tr></thead><tbody><tr><td>端口被占用</td><td>查看启动日志，确认 <code>EADDRINUSE</code> 错误；检查是否有旧进程残留</td></tr><tr><td>无法连接 WebSocket</td><td>检查 Token 是否正确，浏览器 WebSocket 不支持自定义 Header，需使用 <code>?token=</code></td></tr><tr><td>文件操作被拒绝</td><td>检查 <code>allowedPaths</code> 是否包含目标路径，确认路径白名单校验</td></tr><tr><td>命令执行被拒绝</td><td>查看命令安全检查级别，deny 直接拒绝，confirm 需前端确认</td></tr><tr><td>RAG 不可用</td><td>调用 <code>/api/rag/detect</code> 查看探测结果，必要时执行 <code>/api/rag/install</code></td></tr><tr><td>日志过多</td><td>使用 <code>/api/logs/query</code> 查询最近 7 天日志，按类别过滤</td></tr><tr><td>进程卡住不退出</td><td>检查优雅关闭是否触发，确认 10 秒超时是否生效</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2156-L2163" target="_blank" rel="noreferrer">agent/src/server.js#L2156-L2163</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1674" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1674</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2025-L2072" target="_blank" rel="noreferrer">agent/src/server.js#L2025-L2072</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1705-L1725" target="_blank" rel="noreferrer">agent/src/server.js#L1705-L1725</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2288" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2288</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Agent 本地代理服务采用单进程多路由架构，以原生 <code>http</code> 与 <code>ws</code> 实现 HTTP 与 WebSocket 服务，通过统一请求处理器实现路由、认证、日志、配置与安全策略。其优势在于轻量、可控、易于调试；风险在于单进程阻塞与长驻进程模块缓存。部署时应严格限制网络暴露范围，合理配置端口与白名单，并利用健康检查、日志查询与优雅关闭机制保障稳定性。对于 Chrome 扩展侧，需注意 MV3 Service Worker 生命周期约束，确保保活与消息传递正确。</p><p>[本节为总结性内容，不直接分析具体文件]</p>`,100)])])}const b=t(i,[["render",l]]);export{p as __pageData,b as default};
